"""
SmartTech Points List Extractor (v3)
Extracts "Typical Points Summary" tables from IFC drawing sets into Excel,
one tab per equipment type, with optional submittal-driven point expansion.
All processing is local. No external calls.
"""
import io
import re
import datetime

import fitz  # PyMuPDF
import pandas as pd
import streamlit as st
from openpyxl import Workbook
from openpyxl.styles import Alignment, Border, Font, PatternFill, Side
from openpyxl.utils import get_column_letter

APP_TITLE = "SmartTech Points List Extractor"
DEFAULT_MARKER = "TYPICAL POINTS SUMMARY"

# SmartTech Contracting logo (extracted from the delivered TATSU points list).
SMARTTECH_LOGO_B64 = ""

STC_NAVY, STC_ORANGE = "#020C3D", "#EC7626"


def logo_bytes():
    import base64 as _b64
    try:
        return _b64.b64decode(SMARTTECH_LOGO_B64)
    except Exception:
        return None


st.set_page_config(page_title=APP_TITLE, layout="wide")


# ---------------------------------------------------------------- helpers ----
def squash(s):
    """Uppercase and strip ALL whitespace - CAD plots often letter-space text."""
    return re.sub(r"\s+", "", s or "").upper()


def page_lines(page):
    """All text lines as (y_center, x0, x1, text), clustered by baseline."""
    words = sorted(page.get_text("words"), key=lambda w: ((w[1] + w[3]) / 2, w[0]))
    lines, cur, cur_y = [], [], None
    for w in words:
        y = (w[1] + w[3]) / 2
        if cur_y is None or abs(y - cur_y) < 3:
            cur.append(w)
            cur_y = y if cur_y is None else (cur_y + y) / 2
        else:
            lines.append((cur_y, cur))
            cur, cur_y = [w], y
    if cur:
        lines.append((cur_y, cur))
    out = []
    for y, ws_ in lines:
        ws_.sort(key=lambda w: w[0])
        # Side-by-side viewports put unrelated text on one baseline: split the
        # cluster wherever the horizontal gap between words is large.
        seg = [ws_[0]]
        segs = []
        for w in ws_[1:]:
            if w[0] - seg[-1][2] > 100:
                segs.append(seg)
                seg = [w]
            else:
                seg.append(w)
        segs.append(seg)
        for s in segs:
            out.append((y, min(w[0] for w in s), max(w[2] for w in s),
                        norm_cell(" ".join(w[4] for w in s))))
    return out


def find_marker_lines(page, marker):
    """Lines whose squashed text contains the squashed marker: (y, x0, x1, text)."""
    m = squash(marker)
    return [ln for ln in page_lines(page) if m in squash(ln[3])]


def page_title_anchors(page):
    """Points-table title lines on the page: (y, x0, x1, text)."""
    return [ln for ln in page_lines(page)
            if len(ln[3]) <= 130 and is_title_line(ln[3])]


def valid_title_anchors(page, anchors):
    """Keep only anchors that sit inside, or within 60pt above, an actual
    detected table with x-overlap. Viewport bands and notes lines that merely
    mention points-list keywords must not carve the page."""
    try:
        tf = page.find_tables()
        boxes = [t.bbox for t in tf.tables if t.row_count >= 3 and t.col_count >= 3] if tf else []
    except Exception:
        boxes = []
    out = []
    for a in anchors:
        y, x0, x1 = a[0], a[1], a[2]
        for bx0, by0, bx1, by1 in boxes:
            if x1 > bx0 - 5 and x0 < bx1 + 5 and by0 - 60 <= y <= by1:
                out.append(a)
                break
    return out


def build_title_regions(anchors, prect):
    """One clip rect per title: x-band = the title's column of tables (columns
    are clusters of title x-starts), y from this title down to the next title
    in the same column. Detecting tables inside these clips keeps adjacent
    tables from fusing into one grid."""
    xs = sorted({a[1] for a in anchors})
    col_starts = []
    for x in xs:
        if not col_starts or x - col_starts[-1] > 150:
            col_starts.append(x)
    bounds = []
    for i, x in enumerate(col_starts):
        x0 = x - 12
        x1 = (col_starts[i + 1] - 14) if i + 1 < len(col_starts) else prect.x1
        bounds.append((x0, x1))
    def col_of(a):
        return max(i for i, (x0, _x1) in enumerate(bounds) if a[1] >= x0)
    regions = []
    for a in anchors:
        ci = col_of(a)
        below = [b[0] for b in anchors if col_of(b) == ci and b[0] > a[0] + 4]
        y1 = (min(below) - 6) if below else prect.y1
        regions.append((fitz.Rect(bounds[ci][0], a[0] - 12, bounds[ci][1], y1), a[3]))
    return regions


def norm_cell(v):
    """Collapse whitespace/newlines PyMuPDF leaves in extracted cells."""
    if v is None:
        return ""
    return re.sub(r"\s+", " ", str(v).replace("\r", " ").replace("\n", " ")).strip()


def sanitize_sheet_name(name, used):
    bad = r'[]:*?/\\'
    clean = "".join(c for c in name if c not in bad).strip() or "Sheet"
    clean = clean[:31]
    base, n = clean, 2
    while clean.lower() in used:
        suffix = f" ({n})"
        clean = base[: 31 - len(suffix)] + suffix
        n += 1
    used.add(clean.lower())
    return clean


# Squashed keywords that mark a line as a points-table title. Covers the
# wording seen across BAS drawing sets; auto-detect works even when none match.
TITLE_KEYS = ["TYPICALPOINTSSUMMARY", "POINTSSUMMARY", "POINTSUMMARY",
    "POINTSLIST", "POINTLIST", "POINTSSCHEDULE", "POINTSCHEDULE",
    "POINTSMATRIX", "POINTMATRIX", "POINTSTABLE", "IOSUMMARY", "I/OSUMMARY",
    "IOLIST", "I/OLIST", "IOSCHEDULE", "I/OSCHEDULE", "IOMATRIX", "I/OMATRIX",
    "HARDWIREDPOINTS", "SOFTWAREPOINTS", "INTEGRATIONPOINTS", "MODBUSPOINTS",
    "BACNETPOINTS", "SCADAPOINTS", "BASPOINTS", "BMSPOINTS", "DDCPOINTS",
    "CONTROLPOINTS", "MONITORINGPOINTS", "ALARMPOINTS"]

# Trailing title words stripped to get the equipment name for the tab.
TITLE_SUFFIX1 = re.compile(
    r"\s*[-–—:]?\s*(TYPICAL\s+)?(POINTS?|I\s*/?\s*O)\s+"
    r"(SUMMARY|LIST|SCHEDULE|MATRIX|TABLE)\s*$", re.I)
TITLE_SUFFIX2 = re.compile(
    r"\s*[-–—:]?\s*(HARDWIRED|SOFTWARE|INTEGRATION|MODBUS|BACNET|MONITORING|"
    r"CONTROL|ALARM|BAS|BMS|SCADA|DDC|PLC)\s+POINTS?\s*$", re.I)


def is_title_line(s):
    sq = squash(s)
    return any(k in sq for k in TITLE_KEYS)


def short_equipment_name(title, marker=None):
    """'... UNIT (CRAH) - TYPICAL POINTS SUMMARY' -> ('CRAH', '... UNIT (CRAH)');
    'PLC HARDWIRED POINTS LIST' -> ('PLC HARDWIRED', 'PLC HARDWIRED')."""
    eq = title
    if marker:
        eq = re.split(re.escape(marker), eq, flags=re.I)[0]
    # Cut from the first POINTS-keyword to the end - titles often continue
    # after it ("... - POINTS SUMMARY PLC HARDWIRED & INTEGRATION").
    eq = re.sub(r"\s*[-–—:]?\s*(TYPICAL\s+)?POINTS?\s+"
                r"(SUMMARY|LIST|SCHEDULE|MATRIX|TABLE)\b.*$", "", eq, flags=re.I)
    eq = TITLE_SUFFIX2.sub("", eq)
    eq = re.sub(r"\s*[-–—:]\s*TABLE\s*\d*\s*$", "", eq, flags=re.I)
    eq = eq.rstrip(" -–—:").strip() or title
    # Acronym in parens anywhere wins the tab name: "... (VAV) TERMINAL UNIT"
    accs = re.findall(r"\(([A-Z0-9&/ -]{2,8})\)", eq)
    if accs:
        return accs[-1].strip(), eq
    short = eq
    if len(short) > 31:
        for a, b in (("MEDIUM VOLTAGE", "MV"), ("LOW VOLTAGE", "LV"),
                     ("SWITCHGEAR", "SWGR"), ("INTEGRATION", "INTEG"),
                     ("CONTROLLER", "CTRLR"), ("MONITORING", "MON")):
            short = re.sub(a, b, short, flags=re.I)
        short = short.strip()
    return short, eq


def title_line_above(page, bbox, max_gap=60):
    """Nearest text line ending within max_gap above the table, restricted to
    the table's x-band. Prefer lines carrying a points-title keyword."""
    words = [w for w in page.get_text("words")
             if bbox[1] - max_gap < (w[1] + w[3]) / 2 < bbox[1] + 2
             and w[0] >= bbox[0] - 10 and w[2] <= bbox[2] + 10]
    lines = {}
    for w in words:
        key = round((w[1] + w[3]) / 2 / 3)
        lines.setdefault(key, []).append(w)
    best = None
    for key, ws_ in lines.items():
        ws_.sort(key=lambda w: w[0])
        txt = norm_cell(" ".join(w[4] for w in ws_))
        if len(txt) < 4 or len(txt) > 110:
            continue
        y = sum((w[1] + w[3]) / 2 for w in ws_) / len(ws_)
        score = (is_title_line(txt), y)  # keyword first, then closest above
        if best is None or score > best[0]:
            best = (score, txt)
    return best[1] if best else ""


def first_data_row_index(rows):
    """Rows before the first row whose first cell is a bare integer are headers."""
    for i, r in enumerate(rows):
        if r and re.fullmatch(r"\d{1,3}", (r[0] or "").strip()):
            return i
    return 1 if len(rows) > 1 else 0


MARK_RE = re.compile(r"^(X|R|R/W|O|ON|OFF|COS|COV|POLL|BV|AV|AI|AO|DI|DO|\d{1,4})$", re.I)


def is_points_row(row):
    """A real points row has a description, >=3 filled cells, and at least one
    mark-like cell (X / R / COS / a number). SOO paragraphs, frame slices and
    note lines fail at least one of these."""
    filled = [c for c in row if c]
    if len(filled) < 3:
        return False
    if not any(MARK_RE.match(c.strip()) for c in filled):
        return False
    desc = row[1] if len(row) > 1 and row[1] else (filled[1] if len(filled) > 1 else "")
    return bool(re.search(r"[A-Za-z]{2}", desc or " ".join(filled)))


def relocate_trailing_notes(data_rows, notes):
    """NOTES lines drawn inside the table bbox: move them out of the data.
    Long notes can be split across several cells, so match on the first
    filled cell regardless of how many fragments follow."""
    while data_rows:
        filled = [c for c in data_rows[-1] if c]
        if filled and (re.match(r"^NOTES?\b", filled[0], re.I)
                       or re.match(r"^\d+[.)]\s?", filled[0])):
            notes.append(" ".join(filled))
            data_rows.pop()
        else:
            break
    notes.sort(key=lambda n: not re.match(r"^NOTES?\b", n, re.I))
    return data_rows, notes


def table_quality(data_rows):
    """(#points-like rows, fraction). Gate: >=2 rows and >=25% points-like."""
    good = sum(1 for r in data_rows if is_points_row(r))
    frac = good / len(data_rows) if data_rows else 0.0
    return good, frac


def line_text_at(page, y, x_min=None, x_max=None):
    """Join words on the horizontal line at height y, restricted to an x-band
    so text in other viewports/columns at the same height cannot bleed in."""
    words = page.get_text("words")
    line = [w for w in words if abs((w[1] + w[3]) / 2 - y) < 4]
    if x_min is not None:
        line = [w for w in line if w[0] >= x_min - 2]
    if x_max is not None:
        line = [w for w in line if w[2] <= x_max + 2]
    line.sort(key=lambda w: w[0])
    return norm_cell(" ".join(w[4] for w in line))


def notes_below(page, table_bbox):
    """Capture a NOTES block directly below the table, within the table's own
    x-band, so sequences/legends/title blocks elsewhere on the sheet are not
    swept in."""
    x0, x1 = table_bbox[0] - 10, table_bbox[2] + 10
    words = page.get_text("words")
    below = [w for w in words
             if table_bbox[3] - 2 < w[1] < table_bbox[3] + 300
             and w[0] >= x0 and w[2] <= x1]
    if not below:
        return []
    lines = {}
    for w in below:
        key = round((w[1] + w[3]) / 2, 1)
        lines.setdefault(key, []).append(w)
    ordered = []
    for key in sorted(lines):
        ws = sorted(lines[key], key=lambda w: w[0])
        ordered.append(norm_cell(" ".join(w[4] for w in ws)))
    out, in_notes = [], False
    for ln in ordered:
        if not in_notes:
            if re.match(r"^NOTES?\b", ln, re.I):
                in_notes = True
                out.append(ln)
            continue
        # Only the heading and numbered note lines belong to the block;
        # the first anything-else (legend, viewport title band) ends it.
        if re.match(r"^\d+[.)]\s", ln):
            out.append(ln)
        else:
            break
        if len(out) > 15:
            break
    return out

# ------------------------------------------------------------- extraction ----
def desc_header_cols(row):
    """Column indices of POINT DESCRIPTION header cells in a row. Tolerates a
    merged leading ID ('ID POINT DESCRIPTION') but not sentences."""
    return [i for i, c in enumerate(row)
            if c and "POINTDESCRIPTION" in squash(c) and len(c) <= 28]


def split_columns(rows):
    """Two tables drawn side by side can come back fused into one wide table.
    Detect >=2 POINT DESCRIPTION header cells in one row and slice the columns
    into one segment per table (each starting at its ID column)."""
    for r in rows[:10]:
        cols = desc_header_cols(r)
        if len(cols) >= 2:
            starts = [max(c - 1, 0) for c in cols]
            starts[0] = 0
            width = max(len(x) for x in rows)
            segs = []
            for a, b in zip(starts, starts[1:] + [width]):
                seg = [row[a:b] for row in rows]
                segs.append([r2 for r2 in seg if any(c for c in r2)])
            return segs
    return [rows]


def split_row_blocks(rows):
    """Tables stacked vertically can fuse into one tall table. An interior
    title band (points-title keywords, <=3 filled cells) starts a new block."""
    idxs = [0]
    for i in range(1, len(rows)):
        r = rows[i]
        filled = sum(1 for c in r if c)
        if 0 < filled <= 3 and is_title_line(" ".join(c for c in r if c)):
            idxs.append(i)
    blocks = [rows[a:b] for a, b in zip(idxs, idxs[1:] + [len(rows)])]
    return [b for b in blocks if b]


class RebuiltTable:
    """Duck-typed stand-in for a fitz Table, built from raw line geometry."""
    def __init__(self, bbox, cells):
        self.bbox = bbox
        self._cells = cells
        self.row_count = len(cells)
        self.col_count = len(cells[0]) if cells else 0

    def extract(self):
        return self._cells


def _cluster(vals, tol=2.5):
    out = []
    for v in sorted(vals):
        if out and v - out[-1] <= tol:
            out[-1] = (out[-1] + v) / 2
        else:
            out.append(v)
    return out


def rebuild_table_from_lines(page, clip):
    """Last-resort extraction: take the drawn rule lines inside the clip as
    row/column boundaries and bin whole words into cells. Immune to the cell
    text scrambling fitz can produce on dense grids."""
    vxs, hys = [], []
    for d in page.get_drawings():
        for item in d["items"]:
            if item[0] == "l":
                p1, p2 = item[1], item[2]
                mx, my = (p1.x + p2.x) / 2, (p1.y + p2.y) / 2
                if not (clip.x0 - 2 <= mx <= clip.x1 + 2 and clip.y0 - 2 <= my <= clip.y1 + 2):
                    continue
                if abs(p1.x - p2.x) < 1.5 and abs(p1.y - p2.y) > 8:
                    vxs.append(p1.x)
                elif abs(p1.y - p2.y) < 1.5 and abs(p1.x - p2.x) > 8:
                    hys.append(p1.y)
            elif item[0] == "re":
                r = item[1]
                if fitz.Rect(r).intersects(clip):
                    vxs.extend([r.x0, r.x1])
                    hys.extend([r.y0, r.y1])
    xs, ys = _cluster(vxs, 4.0), _cluster(hys, 4.0)
    xs = [x for i, x in enumerate(xs) if i == 0 or x - xs[i - 1] > 6]  # drop slivers
    ys = [y for i, y in enumerate(ys) if i == 0 or y - ys[i - 1] > 6]
    if len(xs) < 4 or len(ys) < 4:
        return None

    def center(w):
        # Rotated text can come back with swapped coordinates - normalize.
        x0, x1 = sorted((w[0], w[2]))
        y0, y1 = sorted((w[1], w[3]))
        return (x0 + x1) / 2, (y0 + y1) / 2

    words = [w for w in page.get_text("words")
             if clip.x0 <= center(w)[0] <= clip.x1 and clip.y0 <= center(w)[1] <= clip.y1]
    nrows, ncols = len(ys) - 1, len(xs) - 1
    cells = [[[] for _ in range(ncols)] for _ in range(nrows)]
    import bisect
    for w in words:
        xc, yc = center(w)
        r = bisect.bisect_right(ys, yc) - 1
        c = bisect.bisect_right(xs, xc) - 1
        if 0 <= r < nrows and 0 <= c < ncols:
            cells[r][c].append(w)
    out = [[" ".join(w[4] for w in sorted(cell, key=lambda w: (round(min(w[1], w[3])), min(w[0], w[2]))))
            for cell in row] for row in cells]
    return RebuiltTable((xs[0], ys[0], xs[-1], ys[-1]), out)


def parse_setpoint_bars(page):
    """Parse the 'SETPOINTS, ALARMS, AND OPERATOR ADJUSTABILITY' bar diagrams.

    Red-filled segments are alarm regions: a segment anchored at the left end
    of the scale sets the LOW limit at its right edge; one anchored at the
    right end sets the HIGH limit at its left edge. The nearest printed number
    to that edge is the limit value; a number floating above the bar is the
    startup/default setpoint. Returns [{name, low, high, default}].
    """
    text = page.get_text("text")
    if "SETPOINTS, ALARMS" not in text.upper():
        return []
    title = next((l for l in page_lines(page) if "SETPOINTS, ALARMS" in l[3].upper()), None)
    if not title:
        return []
    y_top = title[0] + 4
    reds, scales, small_boxes = [], [], []
    for d in page.get_drawings():
        r = d["rect"]
        if r.y0 < y_top or r.y0 > y_top + 700 or r.x1 < title[1] - 40:
            continue
        fill = d.get("fill")
        if fill and fill[0] > 0.7 and fill[1] < 0.4 and fill[2] < 0.4 \
                and r.width > 8 and 3 < r.height < 40:
            reds.append(r)
        elif r.width > 120 and r.height < 40:
            scales.append(r)
        elif 8 < r.width < 70 and r.height < 24:
            small_boxes.append(r)
    if not scales and not reds:
        return []
    # cluster into bar rows by vertical center
    items = [(r, "red") for r in reds] + [(r, "scale") for r in scales]
    items.sort(key=lambda t: (t[0].y0 + t[0].y1) / 2)
    rows, cur, cy = [], [], None
    for r, kind in items:
        y = (r.y0 + r.y1) / 2
        if cy is None or abs(y - cy) < 9:
            cur.append((r, kind))
            cy = y if cy is None else (cy + y) / 2
        else:
            rows.append(cur)
            cur, cy = [(r, kind)], y
    if cur:
        rows.append(cur)

    words = page.get_text("words")
    out = []
    for row in rows:
        rects = [r for r, _k in row]
        bx0, bx1 = min(r.x0 for r in rects), max(r.x1 for r in rects)
        by0, by1 = min(r.y0 for r in rects), max(r.y1 for r in rects)
        # label: text to the left of the bar within the row band
        lbl = [w for w in words if w[2] <= bx0 - 6 and by0 - 16 < (w[1] + w[3]) / 2 < by1 + 16]
        lbl.sort(key=lambda w: (round(w[1]), w[0]))
        name = norm_cell(" ".join(w[4] for w in lbl))
        if not name or "OPERATING RANGE" in name.upper() or "ALARM LIMITS" in name.upper():
            continue
        # numbers around the bar; those above the bar top are default setpoints
        nums = []
        for w in words:
            xc, yc = (w[0] + w[2]) / 2, (w[1] + w[3]) / 2
            if bx0 - 20 <= xc <= bx1 + 20 and by0 - 26 < yc < by1 + 22:
                m = re.fullmatch(r"[\d,]+(\.\d+)?", w[4].strip())
                if m:
                    nums.append((xc, yc, w[4].replace(",", "")))
        # the startup/default setpoint is the number drawn inside a small box
        default = next((v for xc, yc, v in nums
                        if any(bb.x0 - 2 <= xc <= bb.x1 + 2 and bb.y0 - 2 <= yc <= bb.y1 + 2
                               for bb in small_boxes)), None)
        low = high = None
        for r in [r for r, k in row if k == "red"]:
            if r.x0 - bx0 < 6 and bx1 - r.x1 > 20:      # left-anchored: low alarm
                edge = r.x1
                cand = [(abs(xc - edge), v) for xc, yc, v in nums if yc >= by0 - 2]
                if cand:
                    low = min(cand)[1]
            elif bx1 - r.x1 < 6 and r.x0 - bx0 > 20:    # right-anchored: high alarm
                edge = r.x0
                cand = [(abs(xc - edge), v) for xc, yc, v in nums if yc >= by0 - 2]
                if cand:
                    high = min(cand)[1]
        out.append({"name": name, "low": low, "high": high, "default": default})
    return [b for b in out if b["low"] or b["high"] or b["default"]]


def extract_points_tables(pdf_bytes, filename, marker=""):
    """Scan a drawing PDF for points tables (auto mode when marker == "").

    Sheets often carry several points tables; detected title lines carve the
    page into per-table clip regions so adjacent tables cannot fuse into one
    grid. Within a region, candidates are gated by row shape, weak grids
    trigger text-based column retries, and stacked leftovers are split at
    interior title bands. Nothing fails silently.
    """
    entries, report = [], []
    try:
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
    except Exception as exc:
        report.append({"File": filename, "Page": "-", "Status": f"Could not open PDF: {exc}", "Title": ""})
        return entries, report

    auto = not (marker or "").strip()
    by_title = {}
    any_relevant = False

    def harvest(page, tables, marker_ys, pno, forced_title=None):
        acc, rej = [], []
        for t in sorted(tables, key=lambda t: t.bbox[1]):
            if t.row_count < 3 or t.col_count < 3:
                continue
            raw = [[norm_cell(c) for c in r] for r in t.extract()]
            raw = [r for r in raw if any(c for c in r)]
            if not any(desc_header_cols(r) for r in raw[:12]):
                continue
            for bi, rows in enumerate(split_row_blocks(raw)):
                if not any(desc_header_cols(r) for r in rows[:8]):
                    continue
                split = first_data_row_index(rows)
                header_rows, data_rows = rows[:split], rows[split:]
                title = ""
                inbox = [h for h in header_rows
                         if (is_title_line(" ".join(h)) or
                             (not auto and squash(marker) in squash(" ".join(h))))
                         and sum(1 for c in h if c) <= 3]
                if inbox:
                    title = norm_cell(" ".join(c for c in inbox[0] if c))
                elif bi == 0 and forced_title:
                    title = forced_title
                elif bi == 0 and marker_ys:
                    ys = [a[0] for a in marker_ys]
                    above = [y for y in ys if y <= t.bbox[3]]
                    y = min(above or ys, key=lambda y: abs(y - t.bbox[1]))
                    title = line_text_at(page, y, x_min=t.bbox[0], x_max=t.bbox[2])
                elif bi == 0 and auto:
                    title = title_line_above(page, t.bbox)
                if not title:
                    title = f"Points Table (p{pno + 1}.{bi + 1})"
                header_rows = [h for h in header_rows if h not in inbox]

                if "LEGEND" in squash(title):
                    rej.append({"File": filename, "Page": pno + 1,
                                "Status": "Title identifies this as a legend - skipped",
                                "Title": title})
                    continue
                notes = notes_below(page, t.bbox) if bi == 0 else []
                data_rows, notes = relocate_trailing_notes(data_rows, notes)
                good, frac = table_quality(data_rows)
                if good < 2 or frac < 0.25:
                    rej.append({"File": filename, "Page": pno + 1,
                                "Status": f"Rejected: {good} of {len(data_rows)} rows look like "
                                          "points rows - likely a frame, SOO text box, or a "
                                          "misread grid",
                                "Title": title})
                    continue
                filled = sum(1 for r in data_rows for c in r if c)
                acc.append({"title": title, "header_rows": header_rows,
                            "data_rows": data_rows, "notes": notes,
                            "ncols": max(len(r) for r in rows), "good": good,
                            "filled": filled})
        return acc, rej

    def metrics(a):
        rows = [r for x in a for r in x["data_rows"]]
        good = sum(x["good"] for x in a)
        avgf = (sum(1 for r in rows for c in r if c) / len(rows)) if rows else 0.0
        return good, avgf

    def harvest_best(page, marker_ys, pno, clip=None, forced_title=None):
        """Line-strategy first; density-triggered text retries; challenger must
        be both richer in points rows and denser."""
        def tables_with(**kw):
            try:
                tf = page.find_tables(clip=clip, **kw) if clip else page.find_tables(**kw)
                return list(tf.tables) if tf else []
            except Exception:
                return []
        acc, rej = harvest(page, tables_with(), marker_ys, pno, forced_title)
        good0, avgf0 = metrics(acc)
        if not acc or avgf0 < 3.0:
            best = (good0, avgf0, 0, acc, rej)
            for order, kw in enumerate(({"vertical_strategy": "text"},
                                        {"vertical_strategy": "text",
                                         "horizontal_strategy": "text"}), start=1):
                a2, r2 = harvest(page, tables_with(**kw), marker_ys, pno, forced_title)
                g2, f2 = metrics(a2)
                if a2 and g2 > best[0] and f2 >= max(best[1], 3.0):
                    best = (g2, f2, -order, a2, r2)
            acc, rej = best[3], best[4]
        if not acc and clip is not None:
            # Fourth strategy: rebuild from raw rule-line geometry - immune to
            # the cell scrambling fitz can produce on dense side-by-side grids.
            shim = rebuild_table_from_lines(page, clip)
            if shim:
                a3, r3 = harvest(page, [shim], marker_ys, pno, forced_title)
                if a3:
                    acc, rej = a3, r3
        return acc, rej

    for pno, page in enumerate(doc):
        text = page.get_text("text")
        if auto:
            if "POINTDESCRIPTION" not in squash(text):
                continue
            anchors = page_title_anchors(page)
        else:
            if squash(marker) not in squash(text):
                continue
            anchors = find_marker_lines(page, marker)
        any_relevant = True

        # Whole-page extraction is always the baseline. Region carving only
        # replaces it when the page shows fusion evidence (an implausibly wide
        # fused grid, or nothing extracted) AND carving yields more tables -
        # so single-table sheets can never be degraded by carving.
        page_bars = parse_setpoint_bars(page)
        acc, rej = harvest_best(page, anchors, pno)
        fused = (not acc) or any(x["ncols"] >= 34 for x in acc)
        if fused:
            region_anchors = valid_title_anchors(page, anchors) if len(anchors) >= 2 else []
            if len(region_anchors) >= 2:
                r_acc, r_rej = [], []
                for clip, ttl in build_title_regions(region_anchors, page.rect):
                    a, r = harvest_best(page, [], pno, clip=clip, forced_title=ttl)
                    r_acc.extend(a)
                    r_rej.extend(r)
                if len(r_acc) > len(acc):
                    acc, rej = r_acc, r_rej

        if not acc and not rej:
            report.append({"File": filename, "Page": pno + 1,
                           "Status": ("This page has POINT DESCRIPTION text but no readable "
                                      "table grid (manual review needed)" if auto else
                                      "Marker found but no points-table grid detected "
                                      "(manual review needed)"),
                           "Title": anchors[0][3] if anchors else ""})
        report.extend(rej)
        for a in acc:
            key = a["title"].upper()
            if key in by_title:
                if pno + 1 in by_title[key]["pages"]:
                    continue
                by_title[key]["data_rows"].extend(a["data_rows"])
                by_title[key]["pages"].append(pno + 1)
                status = "Continuation rows appended"
            else:
                short, eq = short_equipment_name(a["title"], None if auto else marker)
                by_title[key] = {"title": a["title"], "equipment": eq, "short": short,
                                 "file": filename, "pages": [pno + 1],
                                 "header_rows": a["header_rows"],
                                 "data_rows": a["data_rows"], "notes": a["notes"],
                                 "expansions": [], "alarm_bars": page_bars}
                entries.append(by_title[key])
                status = "Extracted"
            report.append({"File": filename, "Page": pno + 1, "Status":
                           f'{status}: {len(a["data_rows"])} rows x {a["ncols"]} cols',
                           "Title": a["title"]})

    if not any_relevant:
        if auto:
            report.append({"File": filename, "Page": "-",
                           "Status": "No POINT DESCRIPTION text found anywhere. Check this is "
                                     "the BAS set with the points tables, and that the PDF has "
                                     "selectable text (not a scan).",
                           "Title": ""})
        else:
            hints = 0
            for pno, page in enumerate(doc):
                t = page.get_text("text")
                if "POINTDESCRIPTION" in squash(t):
                    cands = []
                    for l in t.splitlines():
                        if len(l) >= 120 or not ("SUMMARY" in squash(l) or "POINTS" in squash(l)):
                            continue
                        toks = l.split()
                        if toks and sum(len(x) == 1 for x in toks) > len(toks) * 0.6:
                            cands.append(squash(l))
                        else:
                            cands.append(norm_cell(l))
                    cands = list(dict.fromkeys(x for x in cands if x))[:3]
                    report.append({"File": filename, "Page": pno + 1,
                                   "Status": "Marker not found, but this page has a POINT "
                                             "DESCRIPTION column. Switch to Auto-detect, or copy "
                                             "its real title into the marker box. Candidate "
                                             "titles: " + ("; ".join(cands) if cands else
                                                           "(none readable)"),
                                   "Title": ""})
                    hints += 1
            if not hints:
                report.append({"File": filename, "Page": "-",
                               "Status": "Marker not found on any page and no POINT DESCRIPTION "
                                         "text either. Check this is the BAS set with the points "
                                         "summaries, and that the PDF has selectable text "
                                         "(not a scan).",
                               "Title": ""})
    doc.close()
    return entries, report


# ------------------------------------------------------- submittal engine ----
STOPWORDS = {"the", "of", "and", "a", "an", "to", "in", "on", "for", "with", "or"}


def significant_words(desc):
    return [w for w in re.findall(r"[A-Za-z]{3,}", desc.lower()) if w not in STOPWORDS]


def scan_submittal_for_expansions(pdf_bytes, filename, entry, desc_col):
    """Propose per-point quantity expansions with cited evidence.

    Match: a submittal line must hit at least half of a point description's
    significant word stems. Quantity evidence: qty/quantity labels, (N)
    parentheticals, or a leading count next to the matched component word.
    Proposals only - the engineer confirms counts in the UI before applying.
    """
    proposals = []
    try:
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
    except Exception:
        return proposals
    pages = [(i + 1, doc[i].get_text("text")) for i in range(len(doc))]
    doc.close()
    if sum(len(t) for _, t in pages) < 200:
        return [{"row": -1, "desc": "", "qty": 0, "page": 0, "file": filename,
                 "evidence": "No readable text in this submittal (likely scanned images) - "
                             "expansion scan not possible."}]

    for ridx, row in enumerate(entry["data_rows"]):
        desc = row[desc_col] if desc_col < len(row) else ""
        words = significant_words(desc)
        if not words:
            continue
        stems = [w[:5] for w in words]
        need = max(1, (len(stems) + 1) // 2)
        best = None
        for pno, text in pages:
            for line in text.splitlines():
                ll = line.lower()
                hits = [s for s in stems if s in ll]
                if len(hits) < need:
                    continue
                qty = None
                m = (re.search(r"\b(?:qty|quantity)\.?:?\s*\(?\s*(\d{1,3})\s*\)?", ll)
                     or re.search(r"\((\d{1,3})\)", line)
                     or re.search(r"\b(\d{1,2})\s+(?:x\s+)?\w*" + re.escape(hits[0]), ll))
                if m:
                    qty = int(m.group(1))
                score = (1 if qty else 0, len(hits))
                if best is None or score > best[0]:
                    best = (score, {"row": ridx, "desc": desc, "qty": qty or 2,
                                    "page": pno, "file": filename,
                                    "evidence": norm_cell(line)[:160]})
        # Only propose with quantity evidence, and only for counts of 2+ -
        # a detected quantity of 1 means a single instance: nothing to expand.
        if best and best[0][0] >= 1 and best[1]["qty"] >= 2:
            proposals.append(best[1])
    return proposals


def apply_expansion(entry, row_index, count, desc_col, source=""):
    """Replace one point row with `count` numbered copies, inserted in place."""
    rows = entry["data_rows"]
    if not (0 <= row_index < len(rows)) or count < 2:
        return
    base = rows[row_index]
    desc = base[desc_col] if desc_col < len(base) else ""
    new = []
    for i in range(1, count + 1):
        r = list(base)
        if desc_col < len(r):
            r[desc_col] = f"{desc} {i}"
        new.append(r)
    entry["data_rows"] = rows[:row_index] + new + rows[row_index + 1:]
    # Renumber the ID column for every numbered row.
    n = 0
    for r in entry["data_rows"]:
        if r and re.fullmatch(r"\d{1,3}", (r[0] or "").strip()):
            n += 1
            r[0] = str(n)
    entry["expansions"].append(
        {"desc": desc, "count": count, "at": row_index, "source": source})

# ------------------------------------------------------------ excel writer ----
THIN = Side(style="thin", color="999999")
BORDER = Border(left=THIN, right=THIN, top=THIN, bottom=THIN)
HDR_FILL = PatternFill("solid", fgColor="DCE6F1")
EXP_FILL = PatternFill("solid", fgColor="FFFF00")  # inserted rows: verify these


def merge_group_row(ws, row_vals, xl_row):
    """Rebuild merged group-header spans: a value followed by blanks = one span."""
    n = len(row_vals)
    c = 0
    while c < n:
        if row_vals[c]:
            end = c
            while end + 1 < n and not row_vals[end + 1]:
                end += 1
            if end > c:
                ws.merge_cells(start_row=xl_row, start_column=c + 1,
                               end_row=xl_row, end_column=end + 1)
        c += 1


def build_workbook(entries):
    wb = Workbook()
    wb.remove(wb.active)
    used = set()
    for e in entries:
        ws = wb.create_sheet(sanitize_sheet_name(e["short"] or e["equipment"], used))
        ncols = max((len(r) for r in e["header_rows"] + e["data_rows"]), default=1)

        ws.cell(row=1, column=1, value=e["title"]).font = Font(name="Arial", bold=True, size=12)
        if ncols > 1:
            ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=ncols)
        _add_logo(ws, anchor="A2", height=40)
        xl_row = 3

        header_rows = e["header_rows"]
        for hidx, hrow in enumerate(header_rows):
            is_last = hidx == len(header_rows) - 1
            for cidx in range(ncols):
                val = hrow[cidx] if cidx < len(hrow) else ""
                cell = ws.cell(row=xl_row, column=cidx + 1, value=val)
                cell.font = Font(name="Arial", bold=True, size=8)
                cell.fill = HDR_FILL
                cell.border = BORDER
                if is_last and cidx >= 3 and len(val) > 6:
                    cell.alignment = Alignment(textRotation=90, horizontal="center",
                                               vertical="bottom", wrap_text=True)
                else:
                    cell.alignment = Alignment(horizontal="center", vertical="center",
                                               wrap_text=True)
            if not is_last:
                merge_group_row(ws, [hrow[c] if c < len(hrow) else "" for c in range(ncols)], xl_row)
            else:
                ws.row_dimensions[xl_row].height = 110
            xl_row += 1

        expanded_descs = {x["desc"] for x in e["expansions"]}
        desc_col = guess_desc_col(e)
        first_data = xl_row
        for r in e["data_rows"]:
            for cidx in range(ncols):
                val = r[cidx] if cidx < len(r) else ""
                cell = ws.cell(row=xl_row, column=cidx + 1, value=val)
                cell.font = Font(name="Arial", size=9)
                cell.border = BORDER
                cell.alignment = Alignment(horizontal="left" if cidx == desc_col else "center",
                                           vertical="center", wrap_text=(cidx == desc_col))
                if expanded_descs and cidx == desc_col and re.match(
                        r"^(" + "|".join(re.escape(d) for d in expanded_descs) + r") \d+$", val or ""):
                    for cc in range(ncols):
                        ws.cell(row=xl_row, column=cc + 1).fill = EXP_FILL
            xl_row += 1

        ws.freeze_panes = ws.cell(row=first_data, column=3)
        xl_row += 1
        for note in e["notes"]:
            ws.cell(row=xl_row, column=1, value=note).font = Font(name="Arial", size=8)
            xl_row += 1
        for x in e["expansions"]:
            ws.cell(row=xl_row, column=1,
                    value=f'EXPANDED (verify): "{x["desc"]}" x{x["count"]} from {x["source"]} '
                          f"- highlighted rows").font = Font(name="Arial", size=8, italic=True,
                                                             color="9C6500")
            xl_row += 1

        widths = {1: 5, 2: 46, 3: 16}
        for c in range(1, ncols + 1):
            ws.column_dimensions[get_column_letter(c)].width = widths.get(c, 5.5)

    meta = wb.create_sheet("Extraction Log", 0)
    meta["A1"] = "SmartTech Points List Extractor - generated "
    meta["A1"] = meta["A1"].value + datetime.date.today().isoformat()
    meta["A1"].font = Font(name="Arial", bold=True)
    meta.append([])
    meta.append(["Sheet", "Source File", "Drawing Pages", "Points", "Expansions Applied"])
    for c in meta[3]:
        c.font = Font(name="Arial", bold=True)
    for e in entries:
        meta.append([e["short"] or e["equipment"], e["file"],
                     ", ".join(map(str, e["pages"])), len(e["data_rows"]),
                     "; ".join(f'{x["desc"]} x{x["count"]}' for x in e["expansions"]) or "None"])
    for col, w in zip("ABCDE", (28, 40, 14, 8, 50)):
        meta.column_dimensions[col].width = w
    for row in meta.iter_rows():
        for c in row:
            if not c.font.bold:
                c.font = Font(name="Arial", size=10)

    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


def guess_desc_col(entry):
    """Find the POINT DESCRIPTION column from the header; default to col 1."""
    for hrow in reversed(entry["header_rows"]):
        for i, v in enumerate(hrow):
            if v and "DESCRIPTION" in v.upper():
                return i
    return 1



# ------------------------------------------------ submittal object tables ----
BACNET_TYPE_MAP = {"ANALOG_INPUT": "AI", "ANALOG_OUTPUT": "AO", "ANALOG_VALUE": "AV",
                   "BINARY_INPUT": "DI", "BINARY_OUTPUT": "DO", "BINARY_VALUE": "BV",
                   "MULTI_STATE_INPUT": "MSI", "MULTI_STATE_OUTPUT": "MSO",
                   "MULTI_STATE_VALUE": "MSV"}
UNIT_TAIL = {"deg", "f", "c", "wc", "in", "gpm", "%", "cfm", "hours", "seconds",
             "hz", "kw", "kwh", "a", "v", "psi", "rpm", "ppm", "rh"}
STATES_UNITS_MAP = {"off,on": "Off / On", "on,off": "On / Off",
                    "normal,alarm": "Normal / Alarm", "alarm,normal": "Alarm / Normal"}
UNITS_DISPLAY = {"deg f": "°F", "deg c": "°C", "in wc": '"W.C.', "wc": '"W.C.'}

_OBJ_ROW = re.compile(
    r"^OBJECT_([A-Z_]+):(\d+)\s+\d+\s+(.+?)\s+"
    r"(AI|AO|AV|BI|BO|BV|MSI|MSO|MSV|Device)\s+(\d+)\s+(.+)$")


def _visual_rows(page):
    words = sorted(page.get_text("words"), key=lambda w: ((w[1] + w[3]) / 2, w[0]))
    rows, cur, cy = [], [], None
    for w in words:
        y = (w[1] + w[3]) / 2
        if cy is None or abs(y - cy) < 3:
            cur.append(w)
            cy = y if cy is None else (cy + y) / 2
        else:
            rows.append(cur)
            cur, cy = [w], y
    if cur:
        rows.append(cur)
    out = []
    for ws_ in rows:
        ws_.sort(key=lambda w: w[0])
        out.append(" ".join(w[4] for w in ws_))
    return out


def parse_bacnet_objects(pdf_bytes):
    """Extract the submittal's BACnet object table (keyname / object name /
    type / instance / description / units / states) into structured records."""
    objects = []
    try:
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
    except Exception:
        return objects
    for pno in range(len(doc)):
        text = doc[pno].get_text("text")
        if "OBJECT_" not in text:
            continue
        for line in _visual_rows(doc[pno]):
            m = _OBJ_ROW.match(norm_cell(line))
            if not m or m.group(4) == "Device":
                continue
            keytype, _inst1, objname, _typ, instance, tail = m.groups()
            tag = ""
            dot_toks = [t for t in objname.split() if "." in t]
            if dot_toks:
                tag = dot_toks[-1].rsplit(".", 1)[-1].strip(".,;")
            toks = tail.split()
            states, units_toks = "", []
            while toks:
                t = toks[-1]
                if "," in t and not t[-1].isdigit():
                    states = t
                    toks.pop()
                elif t.upper() == "N/A":
                    toks.pop()
                elif t.lower().strip(".") in UNIT_TAIL:
                    units_toks.insert(0, t)
                    toks.pop()
                else:
                    break
            objects.append({"tag": tag, "type": BACNET_TYPE_MAP.get(keytype, keytype),
                            "address": instance, "desc": " ".join(toks),
                            "units": " ".join(units_toks), "states": states,
                            "page": pno + 1})
    doc.close()
    return objects


# Canonical word forms so drawing wording matches vendor wording:
# Temperature<->Temp, Setpoint<->SP, CHW<->Cooling, etc.
CANON_WORDS = {"temperature": "temp", "setpoint": "sp", "stpt": "sp",
               "command": "cmd", "position": "pos", "pressure": "press",
               "differential": "diff", "dp": "diff", "humidity": "hum",
               "rh": "hum", "frequency": "freq", "chw": "clg", "cooling": "clg",
               "chilled": "clg", "temp": "temp"}
# Extra words on a candidate that change its meaning: a match must not add
# these unless the drawing point has them too ("General Alarm" must never
# fill from "General Alarm Delay 1").
MEANING_EXTRAS = {"delay", "sp", "rate", "runtime", "limit", "threshold",
                  "factor", "restart", "max", "maximum", "min", "minimum",
                  "fail", "failure", "speed"}


def _base_words(desc):
    words, nums = [], []
    for w in re.findall(r"[A-Za-z]+|\d+", (desc or "").lower()):
        if w.isdigit():
            nums.append(int(w))
        elif w not in STOPWORDS and len(w) >= 2:
            words.append(CANON_WORDS.get(w, w))
    return frozenset(words), nums


def derive_units(obj):
    s = STATES_UNITS_MAP.get((obj.get("states") or "").lower())
    if s:
        return s
    u = (obj.get("units") or "").lower()
    return UNITS_DISPLAY.get(u, obj.get("units") or "")


def match_points_to_objects(entry, objects, desc_col):
    """Match drawing points to submittal objects.

    Numbered families (Supply Fan 1..9 Status) matching one drawing point ->
    expansion proposal with per-instance tag/type/address. Single objects whose
    words cover the drawing point's words -> fill proposal (tag/type/address).
    """
    families = {}
    for o in objects:
        base, nums = _base_words(o["desc"])
        if len(nums) == 1 and base:
            families.setdefault(base, []).append((nums[0], o))
    families = {b: sorted(v) for b, v in families.items()
                if len(v) >= 2 and len({n for n, _ in v}) == len(v)}

    expansions, fills = [], []
    for ridx, row in enumerate(entry["data_rows"]):
        desc = row[desc_col] if desc_col < len(row) else ""
        dwords, _ = _base_words(desc)
        if not dwords:
            continue
        fam = families.get(dwords)
        if fam:
            expansions.append({"row": ridx, "desc": desc, "count": len(fam),
                               "instances": [o for _n, o in fam],
                               "page": fam[0][1]["page"]})
            continue
        best = None
        for o in objects:
            owords, onums = _base_words(o["desc"])
            if onums and owords in families:
                continue  # family members only serve expansions
            if not owords >= dwords:
                continue
            if (owords - dwords) & MEANING_EXTRAS:
                continue  # candidate adds meaning-changing words - not a match
            jacc = len(dwords) / len(owords | dwords)
            if jacc >= 0.5 and (best is None or jacc > best[0]):
                best = (jacc, o)
        if best:
            fills.append({"row": ridx, "desc": desc, "obj": best[1],
                          "page": best[1]["page"]})
    return expansions, fills


def apply_object_expansion(entry, row_index, exp, desc_col, source=""):
    """Expand a drawing row into one numbered row per submittal instance and
    record each instance's tag/type/address for the TATSU export."""
    instances = exp["instances"]
    apply_expansion(entry, row_index, len(instances), desc_col, source=source)
    fills = entry.setdefault("fills", {})
    for i, obj in enumerate(instances, start=1):
        fills[smart_title(f'{exp["desc"]} {i}')] = {
            "tag": obj["tag"], "type": obj["type"], "address": obj["address"],
            "units": derive_units(obj), "src": source}


def apply_object_fill(entry, fill, source=""):
    obj = fill["obj"]
    entry.setdefault("fills", {})[smart_title(fill["desc"])] = {
        "tag": obj["tag"], "type": obj["type"], "address": obj["address"],
        "units": derive_units(obj), "src": source}


